def backfill_breakdowns(apps, schema_editor):
    """Old bookings were priced as days x daily rate; record that as a one-line breakdown."""
    Booking = apps.get_model("rental", "Booking")
    for booking in Booking.objects.using(schema_editor.connection.alias).iterator():
        if booking.price_breakdown:
            continue
        days = (booking.end_date - booking.start_date).days + 1
        rate = booking.quoted_daily_rate or (booking.total_price / days)
        total = f"{booking.total_price:.2f}"
        booking.price_breakdown = {
            "days": days,
            "lines": [{"kind": "rental", "label": f"{days} day{'s' if days != 1 else ''} × ₹{rate:.2f}", "amount": total}],
            "subtotal": total, "discount": "0.00", "rental_total": total, "deposit": "0.00",
            "due_now": total, "total_price": total,
        }
        booking.save(update_fields=["price_breakdown"])


